class Solution {
  public long maxProduct(int[] nums) {
    int max = 0;
    for (int x : nums) max = Math.max(max, x);
    // size the subset table by the largest element's bit length, not a fixed 2^20 on every test
    int bits = 32 - Integer.numberOfLeadingZeros(max), size = 1 << bits;
    int[] best = new int[size]; // best[mask] = largest element whose bits are a subset of mask
    for (int x : nums) best[x] = Math.max(best[x], x);
    for (int b = 0; b < bits; b++)
      for (int mask = 0; mask < size; mask++)
        if ((mask >> b & 1) != 0 && best[mask ^ (1 << b)] > best[mask]) best[mask] = best[mask ^ (1 << b)];
    long ans = 0;
    for (int x : nums) {
      int partner = best[(size - 1) ^ x];
      if (partner > 0) ans = Math.max(ans, (long) x * partner);
    }
    return ans;
  }
}
